// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./UserRoleAccess.sol";

/**
 * @title FileHashRegistry
 * @dev Enterprise SHA-256 Document Fingerprint Registry with RBAC, Batching, and Revocation for dOS Workspace
 * @author Shashank Sharma (MCA Semester 3)
 */
contract FileHashRegistry is UserRoleAccess {
    struct FileRecord {
        bytes32 sha256Hash;
        address owner;
        uint256 timestamp;
        uint256 fileSize;
        string metadataUri;
        bool isTesseraPrivate;
        bool isRevoked;
        string revocationReason;
        uint256 auditCount;
    }

    mapping(bytes32 => FileRecord) public records;

    event FileHashRegistered(
        bytes32 indexed sha256Hash,
        address indexed owner,
        bool isTesseraPrivate,
        uint256 fileSize,
        uint256 timestamp
    );
    event BatchHashesRegistered(uint256 totalRegistered, address indexed owner);
    event FileHashRevoked(bytes32 indexed sha256Hash, string reason, address indexed revokedBy);
    event IntegrityAudited(bytes32 indexed sha256Hash, address indexed auditor, uint256 auditTimestamp);

    constructor() UserRoleAccess() {}

    /**
     * @notice Registers a new document SHA-256 fingerprint with enterprise metadata
     */
    function registerFileHash(
        bytes32 _sha256Hash,
        bool _isTesseraPrivate,
        uint256 _fileSize,
        string calldata _metadataUri
    ) public onlyRole(USER_ROLE) {
        require(_sha256Hash != bytes32(0), "FileHashRegistry: Invalid SHA-256 hash");
        require(records[_sha256Hash].timestamp == 0, "FileHashRegistry: File hash already registered on ledger");

        records[_sha256Hash] = FileRecord({
            sha256Hash: _sha256Hash,
            owner: msg.sender,
            timestamp: block.timestamp,
            fileSize: _fileSize,
            metadataUri: _metadataUri,
            isTesseraPrivate: _isTesseraPrivate,
            isRevoked: false,
            revocationReason: "",
            auditCount: 0
        });

        emit FileHashRegistered(_sha256Hash, msg.sender, _isTesseraPrivate, _fileSize, block.timestamp);
    }

    /**
     * @notice Registers multiple file hashes in a single transaction for gas optimization
     */
    function registerBatchFileHashes(bytes32[] calldata _hashes, bool _isTesseraPrivate) external onlyRole(USER_ROLE) {
        uint256 len = _hashes.length;
        require(len > 0, "FileHashRegistry: Batch list cannot be empty");

        uint256 registeredCount = 0;
        for (uint256 i = 0; i < len; i++) {
            if (_hashes[i] != bytes32(0) && records[_hashes[i]].timestamp == 0) {
                records[_hashes[i]] = FileRecord({
                    sha256Hash: _hashes[i],
                    owner: msg.sender,
                    timestamp: block.timestamp,
                    fileSize: 0,
                    metadataUri: "",
                    isTesseraPrivate: _isTesseraPrivate,
                    isRevoked: false,
                    revocationReason: "",
                    auditCount: 0
                });
                registeredCount++;
                emit FileHashRegistered(_hashes[i], msg.sender, _isTesseraPrivate, 0, block.timestamp);
            }
        }

        emit BatchHashesRegistered(registeredCount, msg.sender);
    }

    /**
     * @notice Revokes a previously registered hash (e.g., corrupted or deprecated document)
     */
    function revokeFileHash(bytes32 _sha256Hash, string calldata _reason) external onlyRole(AUDITOR_ROLE) {
        FileRecord storage rec = records[_sha256Hash];
        require(rec.timestamp > 0, "FileHashRegistry: Hash not found");
        require(!rec.isRevoked, "FileHashRegistry: Hash already revoked");

        rec.isRevoked = true;
        rec.revocationReason = _reason;

        emit FileHashRevoked(_sha256Hash, _reason, msg.sender);
    }

    /**
     * @notice Performs formal security/compliance audit on document integrity
     */
    function auditIntegrity(bytes32 _sha256Hash) external onlyRole(AUDITOR_ROLE) {
        FileRecord storage rec = records[_sha256Hash];
        require(rec.timestamp > 0, "FileHashRegistry: Hash not found");
        require(!rec.isRevoked, "FileHashRegistry: Cannot audit revoked hash");

        rec.auditCount++;
        emit IntegrityAudited(_sha256Hash, msg.sender, block.timestamp);
    }

    /**
     * @notice Verifies hash integrity, ownership, revocation status, and metadata
     */
    function verifyHash(bytes32 _sha256Hash)
        external
        view
        returns (
            bool exists,
            address fileOwner,
            uint256 timestamp,
            uint256 fileSize,
            string memory metadataUri,
            bool isTesseraPrivate,
            bool isRevoked,
            string memory revocationReason,
            uint256 auditCount
        )
    {
        FileRecord memory rec = records[_sha256Hash];
        return (
            rec.timestamp > 0,
            rec.owner,
            rec.timestamp,
            rec.fileSize,
            rec.metadataUri,
            rec.isTesseraPrivate,
            rec.isRevoked,
            rec.revocationReason,
            rec.auditCount
        );
    }
}

contracts/ProjectMilestones.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./UserRoleAccess.sol";

/**
 * @title ProjectMilestones
 * @dev Automated multi-signature escrow & milestone release smart contract for dOS Enterprise Workspace
 * @author Shashank Sharma (MCA Semester 3)
 */
contract ProjectMilestones is UserRoleAccess {
    enum MilestoneStatus { CREATED, IN_PROGRESS, PROOF_SUBMITTED, DISPUTED, RELEASED }

    struct Milestone {
        uint256 id;
        string title;
        uint256 budgetWei;
        MilestoneStatus status;
        bytes32 proofSha256;
        address assignee;
        uint256 approvalsCount;
    }

    mapping(uint256 => Milestone) public milestones;
    mapping(uint256 => mapping(address => bool)) public hasApprovedMilestone;

    event MilestoneCreated(uint256 indexed id, string title, uint256 budgetWei, address assignee);
    event ProofSubmitted(uint256 indexed id, bytes32 proofSha256);
    event MilestoneApproved(uint256 indexed id, address indexed verifier, uint256 totalApprovals);
    event MilestoneDisputed(uint256 indexed id, string reason);
    event MilestoneReleased(uint256 indexed id, uint256 budgetWei, address assignee);

    constructor() UserRoleAccess() {}

    function createMilestone(
        uint256 _id,
        string calldata _title,
        uint256 _budgetWei,
        address _assignee
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(milestones[_id].budgetWei == 0, "ProjectMilestones: Milestone ID already exists");

        milestones[_id] = Milestone({
            id: _id,
            title: _title,
            budgetWei: _budgetWei,
            status: MilestoneStatus.CREATED,
            proofSha256: bytes32(0),
            assignee: _assignee,
            approvalsCount: 0
        });

        emit MilestoneCreated(_id, _title, _budgetWei, _assignee);
    }

    function submitProof(uint256 _id, bytes32 _proofSha256) external {
        Milestone storage m = milestones[_id];
        require(m.id == _id, "ProjectMilestones: Milestone does not exist");
        require(
            msg.sender == m.assignee || hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "ProjectMilestones: Not authorized to submit proof"
        );
        require(_proofSha256 != bytes32(0), "ProjectMilestones: Invalid proof hash");

        m.proofSha256 = _proofSha256;
        m.status = MilestoneStatus.PROOF_SUBMITTED;

        emit ProofSubmitted(_id, _proofSha256);
    }

    function approveMilestone(uint256 _id) external onlyRole(AUDITOR_ROLE) {
        Milestone storage m = milestones[_id];
        require(m.status == MilestoneStatus.PROOF_SUBMITTED, "ProjectMilestones: Proof must be submitted first");
        require(!hasApprovedMilestone[_id][msg.sender], "ProjectMilestones: Already approved by caller");

        hasApprovedMilestone[_id][msg.sender] = true;
        m.approvalsCount++;

        emit MilestoneApproved(_id, msg.sender, m.approvalsCount);

        // Auto release when reaching 2 approvals or admin approval
        if (m.approvalsCount >= 2 || hasRole(DEFAULT_ADMIN_ROLE, msg.sender)) {
            m.status = MilestoneStatus.RELEASED;
            emit MilestoneReleased(_id, m.budgetWei, m.assignee);
        }
    }

    function disputeMilestone(uint256 _id, string calldata _reason) external onlyRole(AUDITOR_ROLE) {
        Milestone storage m = milestones[_id];
        require(m.status != MilestoneStatus.RELEASED, "ProjectMilestones: Cannot dispute released milestone");

        m.status = MilestoneStatus.DISPUTED;
        emit MilestoneDisputed(_id, _reason);
    }
}

contracts/SmartAccountPaymaster.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title SmartAccountPaymaster
 * @dev ERC-4337 Compliant Paymaster Contract for sponsoring dOS enterprise user gas fees
 * @author Shashank Sharma (MCA Semester 3)
 */
contract SmartAccountPaymaster {
    address public owner;
    mapping(address => bool) public approvedUserAccounts;
    uint256 public totalGasSponsoredWei;

    event GasSponsored(address indexed userAccount, uint256 gasAmountWei, bytes32 indexed userOpHash);
    event AccountWhitelisted(address indexed userAccount, bool status);

    modifier onlyOwner() {
        require(msg.sender == owner, "Paymaster: only owner allowed");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    /**
     * @notice Deposit ETH into Paymaster gas pool
     */
    receive() external payable {}

    function depositGasPool() external payable {
        require(msg.value > 0, "Deposit must be greater than zero");
    }

    /**
     * @notice Whitelist a user's ERC-4337 Smart Account for gas-free dOS usage
     */
    function setAccountWhitelist(address _userAccount, bool _status) external onlyOwner {
        approvedUserAccounts[_userAccount] = _status;
        emit AccountWhitelisted(_userAccount, _status);
    }

    /**
     * @notice Validate and sponsor user operation gas fee
     */
    function validateAndSponsorPaymasterOp(
        address _userAccount,
        uint256 _maxGasCost,
        bytes32 _userOpHash
    ) external returns (bool sponsored) {
        require(
            approvedUserAccounts[_userAccount] || _userAccount == owner,
            "Paymaster: user account not whitelisted"
        );
        require(address(this).balance >= _maxGasCost, "Paymaster: insufficient gas pool deposit");

        totalGasSponsoredWei += _maxGasCost;
        emit GasSponsored(_userAccount, _maxGasCost, _userOpHash);

        return true;
    }

    /**
     * @notice Get current Paymaster deposit balance in Wei
     */
    function getGasPoolBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

